text:
{
  "units": {
    "s001": {
      "claims": [
        {
          "claim": "作为2024级学生，主修学业负担较重，希望扩展知识但不追求第二学位，结合2026年秋季学期辅修与微专业相关通知，提出选择与学习安排建议。",
          "evidence_sentence_ids": [],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s002": {
      "claims": [
        {
          "claim": "推荐选择‘微专业’而非辅修。",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "无证据支持‘推荐’或‘优于辅修’的直接陈述。"
    },
    "s003": {
      "claims": [
        {
          "claim": "微专业不授予学位，符合‘不追求第二学位’的目标。",
          "evidence_sentence_ids": [
            "b4_s019"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s004": {
      "claims": [
        {
          "claim": "根据《本科学生学籍管理规定（2026）》第三十四条，修读微专业不授予学位，仅可申请获得微专业修读证书，与辅修学士学位有本质区别。",
          "evidence_sentence_ids": [
            "b4_s019"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s005": {
      "claims": [
        {
          "claim": "微专业课程设置更聚焦于跨学科能力与创新思维，有助于在不增加学位压力的前提下拓展知识面。",
          "evidence_sentence_ids": [
            "b1_s008"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘聚焦跨学科能力与创新思维’为推导，但未明确课程设置内容。"
    },
    "s006": {
      "claims": [
        {
          "claim": "例如‘教师教育’‘全球治理与国际胜任力’‘智能传播’等微专业，均围绕特定领域建设模块化课程群，契合学生个性化发展需求。",
          "evidence_sentence_ids": [
            "b1_s032",
            "b1_s046",
            "b1_s057"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘例如’列举具体微专业，证据中提及但未说明‘模块化课程群’结构。"
    },
    "s007": {
      "claims": [
        {
          "claim": "微专业修读学分可认定为主修专业选修课程学分（最多不超过15学分，其中专业教育不超过5学分），有效缓解学业负担。",
          "evidence_sentence_ids": [
            "b3_s012"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s008": {
      "claims": [
        {
          "claim": "微专业采取单独开班形式上课，避免与主修课程时间冲突，便于时间管理。",
          "evidence_sentence_ids": [
            "b3_s016"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s009": {
      "claims": [
        {
          "claim": "学生可申请免听或缓考，若课程时间冲突，可参照《成绩与考务管理规定》办理，保障学业平衡。",
          "evidence_sentence_ids": [
            "b3_s017"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s010": {
      "claims": [
        {
          "claim": "辅修虽可获得辅修专业证书，但需满足绩点要求（文科3.0、理工科2.8）、每学期仅能辅修一个专业，且辅修学分需在毕业或结业后3年内补修，存在时间与学业压力。",
          "evidence_sentence_ids": [
            "b2_s012",
            "b2_s013",
            "b2_s015",
            "b5_s012"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘存在时间与学业压力’为推论，未直接说明压力程度。"
    },
    "s011": {
      "claims": [
        {
          "claim": "辅修属于‘第二专业’范畴，与‘不追求第二学位’目标存在潜在冲突。",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "无证据表明辅修属于‘第二专业’或与‘不追求第二学位’冲突。"
    },
    "s012": {
      "claims": [
        {
          "claim": "优先选择与主修专业关联度高、知识拓展性强的微专业，如：若主修为教育类专业，可选‘教师教育’微专业，强化教学技能与教育理论。",
          "evidence_sentence_ids": [
            "b1_s032"
          ],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘教育类专业’关联性未在证据中明确，仅提及教师教育方向。"
    },
    "s013": {
      "claims": [
        {
          "claim": "若主修为经管类或国际关系类，可选‘全球治理与国际胜任力’微专业，提升跨文化与国际视野。",
          "evidence_sentence_ids": [
            "b1_s046"
          ],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘经管类或国际关系类’未在证据中定义或关联。"
    },
    "s014": {
      "claims": [
        {
          "claim": "若主修为新闻传播类，可选‘智能传播’微专业，对接产业需求，提升传播技术能力。",
          "evidence_sentence_ids": [
            "b1_s057"
          ],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘新闻传播类’与‘智能传播’关联未明确，仅提及课程名称。"
    },
    "s015": {
      "claims": [
        {
          "claim": "2026年5月17日前，各学院完成辅修/微专业方案设置并公布。",
          "evidence_sentence_ids": [
            "b2_s018"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "仅提及辅修方案设置，未明确微专业方案设置时间。"
    },
    "s016": {
      "claims": [
        {
          "claim": "2026年5月21日至26日，登录‘云南大学网上办事服务大厅’提交微专业申请。",
          "evidence_sentence_ids": [
            "b3_s008"
          ],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "证据中为辅修申请流程，微专业申请流程未明确。"
    },
    "s017": {
      "claims": [
        {
          "claim": "6月25日前，学院公示名单并报教务处备案，6月29日前完成审核。",
          "evidence_sentence_ids": [
            "b3_s007"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s018": {
      "claims": [
        {
          "claim": "审核通过后，在选课系统中完成下学期微专业课程选课。",
          "evidence_sentence_ids": [
            "b3_s008"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s019": {
      "claims": [
        {
          "claim": "每学期修读课程最多不超过34.25学分（含主修课程），若微专业课程与主修课程冲突，可申请免听或缓考。",
          "evidence_sentence_ids": [
            "b3_s014",
            "b3_s017"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s020": {
      "claims": [
        {
          "claim": "微专业课程学分可计入主修专业选修课程，最多不超过15学分，其中专业教育不超过5学分。",
          "evidence_sentence_ids": [
            "b3_s012"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s021": {
      "claims": [
        {
          "claim": "新开设的微专业，若最终选拔人数不足15人，则2026年秋季学期不开课，该微专业本次选拔结果无效，学生下学期重新申请。",
          "evidence_sentence_ids": [
            "b3_s009"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s022": {
      "claims": [
        {
          "claim": "需要确认的信息包括：微专业课程是否与主修课程冲突、辅修资格是否满足、微专业是否开放、课程时间安排、学分认定细则等。",
          "evidence_sentence_ids": [],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "未在证据中明确列出需确认事项，为合理推断。"
    },
    "s023": {
      "claims": [
        {
          "claim": "辅修学分需在毕业或结业后3年内补修，存在时间与学业压力。",
          "evidence_sentence_ids": [
            "b5_s012"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘存在时间与学业压力’为推论，未量化或对比。"
    },
    "s024": {
      "claims": [
        {
          "claim": "微专业修读不授予学位，可申请微专业修读证书。",
          "evidence_sentence_ids": [
            "b4_s019"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s025": {
      "claims": [
        {
          "claim": "学生在修读年限内未修满微专业规定学分，在补修时限内可继续补修未完成学分。",
          "evidence_sentence_ids": [
            "b4_s020"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s026": {
      "claims": [
        {
          "claim": "微专业课程学分可计入主修专业选修课程，最多不超过15学分，其中专业教育不超过5学分。",
          "evidence_sentence_ids": [
            "b3_s012"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    }
  }
}
